from typing import List

from taf.rfrl.procedures.cloud.setups_teardowns.testing_env import TestingEnv
from taf.rfrl.procedures.resources.python.bts.utils.exceptions import ResultError
from taf.rfrl.procedures.resources.python.test_models.cloud.common import (enter_test_dedicated_state,
                                                                           exit_test_dedicated_state,
                                                                           cleanup_after_test_dedicated_state)


def general_siso_auto_cloud_entering_test_dedicated_state_and_running_nr_uplink(testing_env: TestingEnv,
                                                                                cells_names: List[str],
                                                                                interval: float,
                                                                                beam_pattern_id: List[int],
                                                                                frc_index: str,
                                                                                prb_offset: int,
                                                                                ru_mode: str,
                                                                                start_timeout: int = 90,
                                                                                stop_timeout: int = 90):
    """
    Based on:
    QC Test ID: 203676
    QC Test Name: [2.0] CB010411_L_Operability_CB007120_B_Entering_Test_Dedicated_State_and_run_NR_Uplink_Via_Web

    Should report to:
    QC Test ID: 70618
    QC Test Name: General_SiSo_Auto_Cloud_Entering_Test_Dedicated_State_And_Running_NR_Uplink

    :param testing_env: testing environment prepared for this test case
    :param cells_names: names of cells for which NR Uplink test (with same set of parameters) should be run;
                        can be taken from "NRCELL ID" field of cell details in DU WebEM;
                        i.e. ['NRCELL-1', 'NRCELL-3']
    :param interval: reporting time interval to be set before starting NR Uplink test; from <0.1, 3600> range
    :param beam_pattern_id: beam pattern ID to be set before starting NR Uplink test; i.e. [1, 1, 1, 1]
    :param frc_index: FRC index to be set before starting NR Uplink test;
                      one of the following: 'G-FR1-A1-1', 'G-FR1-A1-4', 'G-FR1-A2-1', 'G-FR1-A2-4', 'G-FR1-A1-2', 'G-FR1-A1-5',
                                            'G-FR1-A1-7', 'G-FR1-A2-5'
    :param prb_offset: PRB offset to be set before starting NR Uplink test; from <0, 273> range
    :param ru_mode: RU mode to be set before starting NR Uplink test; one of the following: 'NR_Only', 'MSR', 'Customize_1'
    :param start_timeout: timeout (in seconds) for starting NR Uplink test; defaults to 90
    :param stop_timeout: timeout (in seconds) for stopping NR Uplink test; defaults to 90
    """
    bts = testing_env.btss[0]
    errors = testing_env.errors

    bts.cells.check_if_names_exist(names=cells_names)

    for du in bts.dus:
        enter_test_dedicated_state(du)

        for cell_name in cells_names:
            try:
                _start_nr_uplink_test(du,
                                      cell_name,
                                      interval,
                                      beam_pattern_id,
                                      frc_index,
                                      prb_offset,
                                      ru_mode,
                                      start_timeout)
                _stop_nr_uplink_test(du,
                                     cell_name,
                                     stop_timeout)
            except ResultError as exc:
                errors.add_from_exception(exc)

        exit_test_dedicated_state(du)

    errors.check()


def teardown_for_general_siso_auto_cloud_entering_test_dedicated_state_and_running_nr_uplink(testing_env: TestingEnv):
    """
    Teardown for this test case, must be used in [Teardown] of Robot Framework test suite.
    :param testing_env: testing environment prepared for this test case
    """
    bts = testing_env.btss[0]
    errors = testing_env.errors

    for du in bts.dus:
        cleanup_after_test_dedicated_state(du, errors)


def _start_nr_uplink_test(du,
                          cell_name,
                          interval,
                          beam_pattern_id,
                          frc_index,
                          prb_offset,
                          ru_mode,
                          timeout):
    for cell in du.cells:
        if cell.name == cell_name:
            du.test_model.start_nr_uplink_test(cell=cell,
                                               interval=interval,
                                               beam_pattern_id=beam_pattern_id,
                                               frc_index=frc_index,
                                               prb_offset=prb_offset,
                                               ru_mode=ru_mode,
                                               timeout=timeout)


def _stop_nr_uplink_test(du, cell_name, timeout):
    for cell in du.cells:
        if cell.name == cell_name:
            du.test_model.stop_nr_uplink_test(cell=cell,
                                              timeout=timeout)
